select bb.bookset_id as booksetId, /*账套代码*/ bb.subject_no as subjectNo, /*科目号*/ bb.balance_date as balanceDate, /*余额日期*/ bb.bal_flag as balFlag, /*余额方向*/ NVL(bb.o_amt, 0) as oAmt, /*原币余额*/ NVL(bb.o_d_amt, 0) as oDAmt, /*原币余额借方*/ NVL(bb.o_c_amt, 0) as oCAmt,/*原币余额贷方*/ NVL(O_CO_AMT,0) as oCoAmt, NVL(O_CO_C_AMT,0) as oCoCAmt, NVL(O_CO_D_AMT,0) as oCoDAmt, NVL(TDY_O_C_AMT,0) as tdyOCAmt, NVL(TDY_O_D_AMT,0) as tdyODAmt, NVL(TDY_O_CO_C_AMT,0) as tdyOCoDAmt, NVL(TDY_O_CO_D_AMT,0) as tdyOCoCAmt from BOK_BALANCE bb INNER JOIN REP_PROD_INFO RP ON BB.BOOKSET_ID=RP.F_PROD_ID where RP.PROD_ID= #{booksetId}
AND to_char(bb.balance_date,'yyyy-MM-dd') = #{vdate1,jdbcType=VARCHAR}
and bb.subject_no like '4%' AND to_char(bb.balance_date,'yyyy-MM-dd') > #{vdate1,jdbcType=VARCHAR} AND to_char(bb.balance_date,'yyyy-MM-dd') <= #{mdate,jdbcType=VARCHAR}

