select bb.bookset_id as booksetId, /*账套代码*/ bb.subject_no as subjectNo, /*科目号*/ bb.balance_date as balanceDate, /*余额日期*/ bb.bal_flag as balFlag, /*余额方向*/ NVL(bb.b_amt, 0) as bAmt, /*原币余额*/ NVL(bb.b_d_amt, 0) as bDAmt, /*原币余额借方*/ NVL(bb.b_c_amt, 0) as bCAmt,/*原币余额贷方*/ NVL(B_CO_AMT,0) as bCoAmt, NVL(B_CO_C_AMT,0) as bCoCAmt, NVL(B_CO_D_AMT,0) as bCoDAmt, NVL(TDY_B_C_AMT,0) as tdyBCAmt, NVL(TDY_B_D_AMT,0) as tdyBDAmt, NVL(TDY_B_CO_C_AMT,0) as tdyBCoCAmt, NVL(TDY_B_CO_D_AMT,0) as tdyBCoDAmt, NVL(TDY_PUR_B_D_ULAMT,0) as tdyPurBDUlamt, NVL(TDY_RED_B_D_ULAMT,0) as tdyRedBDUlamt, NVL(TDY_PUR_B_C_ULAMT,0) as tdyPurBCUlamt, NVL(TDY_RED_B_C_ULAMT,0) as tdyRedBCUlamt
from BOK_BALANCE bb INNER JOIN REP_PROD_INFO RP ON BB.BOOKSET_ID=RP.F_PROD_ID where RP.PROD_ID= #{booksetId}
and (bb.subject_no like '2%' or bb.subject_no in ('4002','4003','4011','4103','4104') or bb.subject_no like '6%') and bb.SUBJECT_LEVEL='1' AND to_char(bb.balance_date,'yyyy-MM-dd') = #{vdate1,jdbcType=VARCHAR} union all
